\[
\boxed{
\begin{gathered}
G:\mathbb A_{\mathbb Q}^{2}\setminus\{s=0\}\longrightarrow\mathbb A_{\mathbb Q}^{2},\\[2mm]
G(s,t)=
\left(
\frac{32s^{7}+8s^{3}(s^{2}+t)^{2}+(s^{2}+t)^{5}}{32s^{5}},
\frac{s^{2}+t}{2s}
\right).
\end{gathered}
}
\]

\[
\det DG(s,t)=1,\qquad
G(1,1)=G(-1,-3)=(3,1),\qquad
G\in\mathbb Q[s,s^{-1},t]^2\setminus\mathbb Q[s,t]^2.
\]

\[
\boxed{
\begin{gathered}
X=\{(s,w,t)\in\mathbb A_{\mathbb Q}^{3}:sw=1\},\\[1mm]
H:X\longrightarrow\mathbb A_{\mathbb Q}^{2},\\[1mm]
H(s,w,t)=
\left(
s^{2}+\frac{(s+wt)^{2}}4+\frac{(s+wt)^{5}}{32},
\frac{s+wt}{2}
\right),\\[1mm]
G(s,t)=H(s,s^{-1},t).
\end{gathered}
}
\]

